const test = require('node:test');
const assert = require('node:assert/strict');
const { percentLabel } = require('../progress.cjs');
test('fraction units become percentage units before rounding', () => {
  for (const [fraction,label] of [[0,'0%'],[0.42,'42%'],[1,'100%'],[0.125,'13%'],[0.004,'0%'],[0.999,'100%']]) {
    assert.equal(percentLabel(fraction),label);
  }
});

